mapper.select:
SELECT COUNT(*)
FROM portal_tip_order
WHERE user_id = #{userId}
  AND target_type = #{targetType}
  AND target_id = #{targetId}
  AND status = 'paid'

SELECT t.id, t.user_id, t.author_id, t.target_type, t.target_id, t.amount, t.message,
       t.status, t.pay_method, t.paid_time, t.created_time,
       u.nickname AS user_nickname, u.avatar AS user_avatar,
       a.nickname AS author_nickname, a.avatar AS author_avatar
FROM portal_tip_order t
LEFT JOIN portal_user u ON u.id = t.user_id
LEFT JOIN portal_user a ON a.id = t.author_id


        AND t.target_type = #{targetType}


        AND t.status = #{status}


        AND t.created_time >= #{startTime}


        AND t.created_time <= #{endTime}


ORDER BY t.created_time DESC

SELECT t.id, t.user_id, t.author_id, t.target_type, t.target_id, t.amount, t.message, t.status, t.pay_method, t.paid_time, t.created_time, u.nickname AS user_nickname, u.avatar AS user_avatar, ar.title AS target_title FROM portal_tip_order t LEFT JOIN portal_user u ON u.id = t.user_id LEFT JOIN portal_article ar ON ar.id = t.target_id WHERE t.target_type = 'article_paid'
AND t.status = #{status}
AND t.created_time >= #{startTime}
AND t.created_time <= #{endTime}
ORDER BY t.created_time DESC
